/**
 * External C# API surface for the C# resolver: types that live outside the repo —
 * the .NET Standard 2.1 BCL, the Unity engine/editor assemblies and package
 * sources — described just enough to type a member chain (`transform.parent`,
 * `GetComponent<T>()`) and to walk a base-class chain (`Selectable` →
 * `UIBehaviour` → `MonoBehaviour`).
 *
 * Data comes from two places:
 *   - `data/unity-api.json`, generated by `scripts/gen-unity-api.mjs` from the
 *     reference assemblies (ECMA-335 metadata) and XML docs of the installed
 *     editor, plus the MonoBehaviour/ScriptableObject/Editor message lists of the
 *     ScriptReference of the same Unity version. Committed, so a machine without
 *     Unity resolves identically.
 *   - {@link SEED}: a small hand-checked core, used when the generated file is
 *     absent (a source checkout before generation) and by unit tests.
 *
 * Type references inside the data are C#-shaped text with fully-qualified names:
 * `System.Collections.Generic.List<T>`, `T[]`; a method's own generic parameters
 * are `!!0`, `!!1` (the call's explicit type arguments).
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export interface ApiMember {
  /** Value/return type. */
  t: string;
  /** Methods: return type of the generic overload (`GetComponent<T>()` → `!!0`). */
  tg?: string;
  /** m = method, p = property, f = field, e = event, c = constant. */
  k: "m" | "p" | "f" | "e" | "c";
  s?: 1; // static
}

export interface ApiType {
  k: "class" | "struct" | "interface" | "enum" | "delegate";
  b?: string; // base class (FQN text)
  i?: string[]; // interfaces
  g?: string[]; // generic parameter names
  m?: Record<string, ApiMember>;
  v?: 1; // virtual/abstract members are listed in `vm`
  vm?: string[]; // names of overridable (virtual/abstract) members
}

export interface ApiData {
  /** Where it came from: editor version, generator, date. */
  source: string;
  /** "Namespace.Name`arity" (arity suffix only when generic) → type. */
  types: Record<string, ApiType>;
  /** Engine messages per receiving base class FQN: "UnityEngine.MonoBehaviour" → ["Awake", …]. */
  messages: Record<string, string[]>;
  /** Attribute type FQNs (without the `Attribute` suffix stripped). */
  attributes?: string[];
}

