let loaded: ApiData | null = null;

/** The generated API data when present, else the seed. Read once per process. */
export function apiData(): ApiData {
  if (loaded) return loaded;
  const here = dirname(fileURLToPath(import.meta.url));
  for (const dir of [join(here, "data"), join(here, "..", "..", "src", "graph", "data")]) {
    try {
      const data = JSON.parse(readFileSync(join(dir, "unity-api.json"), "utf8")) as ApiData;
      // The seed stays authoritative for anything the generated data lacks.
      loaded = { ...data, types: { ...SEED.types, ...data.types }, messages: { ...SEED.messages, ...data.messages } };
      return loaded;
    } catch {
      /* try next */
    }
  }
  loaded = SEED;
  return loaded;
}

/** Test seam: replace the API data (null restores lazy loading). */
export function setApiDataForTest(data: ApiData | null): void {
  loaded = data;
}
